<?php
namespace App\Services;
final class PermutationService { public function generate(string $firstName,string $lastName,string $domain,?string $nickname=null):array{$first=$this->clean($firstName);$last=$this->clean($lastName);$nick=$nickname!==null?$this->clean($nickname):'';$dom=strtolower(trim($domain));$fi=$first[0]??'';$li=$last[0]??'';$p=[];if($first&&$last)$p=array_merge($p,["$first.$last","$first$last","{$first}_$last","$last.$first","$last$first","{$last}_$first"]);if($fi&&$last)$p=array_merge($p,["$fi.$last","$fi$last","{$fi}_$last"]);if($first&&$li)$p=array_merge($p,["$first.$li","$first$li","{$first}_$li"]);if($fi&&$li)$p=array_merge($p,["$fi.$li","$fi$li","{$fi}_$li"]);if($first)$p[]=$first;if($last)$p[]=$last;if($nick){$p[]=$nick;if($first&&$last)$p=array_merge($p,["$nick.$last","$first.$nick","$nick$last","$first$nick","{$nick}_$last","{$first}_$nick"]);elseif($first)$p=array_merge($p,["$nick$first","$first$nick","{$nick}_$first","{$first}_$nick"]);elseif($last)$p=array_merge($p,["$nick$last","$last$nick","{$nick}_$last","{$last}_$nick"]);}$out=[];foreach(array_unique($p)as$local){$email="$local@$dom";if(filter_var($email,FILTER_VALIDATE_EMAIL))$out[]=$email;}sort($out);return $out;} private function clean(string $value):string{return preg_replace('/[^a-z0-9]/','',strtolower(trim($value)))??'';}}
